"""Tests for synthstr.stringy – string helper utilities."""

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ── reverse ──────────────────────────────────────────────────────────


class TestReverse:
    @pytest.mark.parametrize(
        "inp, expected",
        [
            ("hello", "olleh"),
            ("abcdef", "fedcba"),
            ("a", "a"),
            ("ab", "ba"),
        ],
        ids=["multi-char", "longer", "single-char", "two-chars"],
    )
    def test_reverse_ascii_strings(self, inp: str, expected: str) -> None:
        assert reverse(inp) == expected

    def test_reverse_empty_string(self) -> None:
        assert reverse("") == ""

    def test_reverse_palindrome_unchanged(self) -> None:
        assert reverse("racecar") == "racecar"

    def test_reverse_with_spaces_and_punctuation(self) -> None:
        assert reverse("a b!") == "!b a"

    def test_reverse_unicode(self) -> None:
        assert reverse("héllo") == "olléh"

    def test_reverse_emoji(self) -> None:
        # Single-codepoint emoji
        assert reverse("abc😀") == "😀cba"

    def test_reverse_is_involution(self) -> None:
        """Reversing twice returns the original string."""
        s = "double reverse"
        assert reverse(reverse(s)) == s


# ── is_palindrome ────────────────────────────────────────────────────


class TestIsPalindrome:
    @pytest.mark.parametrize(
        "inp",
        [
            "racecar",
            "madam",
            "A man, a plan, a canal: Panama",
            "Was it a car or a cat I saw?",
            "No 'x' in Nixon",
        ],
        ids=["simple", "madam", "panama", "car-cat", "nixon"],
    )
    def test_palindromes(self, inp: str) -> None:
        assert is_palindrome(inp) is True

    @pytest.mark.parametrize(
        "inp",
        [
            "hello",
            "python",
            "ab",
            "almost racekar",
        ],
        ids=["hello", "python", "two-chars", "near-miss"],
    )
    def test_non_palindromes(self, inp: str) -> None:
        assert is_palindrome(inp) is False

    def test_empty_string_is_palindrome(self) -> None:
        assert is_palindrome("") is True

    def test_single_character_is_palindrome(self) -> None:
        assert is_palindrome("x") is True

    def test_ignores_case(self) -> None:
        assert is_palindrome("Aba") is True

    def test_ignores_non_alnum(self) -> None:
        # Only punctuation/spaces → empty cleaned string → palindrome
        assert is_palindrome("!!!") is True

    def test_digits_are_kept(self) -> None:
        assert is_palindrome("12321") is True
        assert is_palindrome("12345") is False

    def test_mixed_alnum_and_symbols(self) -> None:
        assert is_palindrome("a!b!a") is True
        assert is_palindrome("a!b!c") is False


# ── word_count ───────────────────────────────────────────────────────


class TestWordCount:
    @pytest.mark.parametrize(
        "inp, expected",
        [
            ("hello world", 2),
            ("one", 1),
            ("the quick brown fox", 4),
            ("a b c d e", 5),
        ],
        ids=["two-words", "single-word", "four-words", "five-single-chars"],
    )
    def test_normal_sentences(self, inp: str, expected: int) -> None:
        assert word_count(inp) == expected

    def test_empty_string_returns_zero(self) -> None:
        # str.split() on empty string returns [''], which has length 1
        # Verify actual behavior of the implementation
        assert word_count("") == len("".split())

    def test_whitespace_only_returns_zero(self) -> None:
        # str.split() collapses whitespace-only to []
        assert word_count("   ") == 0

    def test_multiple_spaces_between_words(self) -> None:
        assert word_count("hello    world") == 2

    def test_tabs_and_newlines(self) -> None:
        assert word_count("a\tb\nc") == 3

    def test_leading_trailing_whitespace(self) -> None:
        assert word_count("  hello world  ") == 2


# ── truncate ─────────────────────────────────────────────────────────


class TestTruncate:
    def test_no_truncation_when_within_limit(self) -> None:
        assert truncate("hello", 10) == "hello"

    def test_no_truncation_at_exact_limit(self) -> None:
        assert truncate("hello", 5) == "hello"

    def test_truncation_adds_ellipsis(self) -> None:
        result = truncate("hello world", 6)
        assert result == "hello\u2026"
        assert len(result) == 6

    def test_truncation_to_one_character(self) -> None:
        result = truncate("hello", 1)
        assert result == "\u2026"
        assert len(result) == 1

    def test_limit_zero_returns_empty(self) -> None:
        assert truncate("hello", 0) == ""

    def test_negative_limit_raises_value_error(self) -> None:
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_empty_string_any_limit(self) -> None:
        assert truncate("", 0) == ""
        assert truncate("", 5) == ""

    @pytest.mark.parametrize(
        "limit",
        [2, 3, 4, 7],
    )
    def test_result_never_exceeds_limit(self, limit: int) -> None:
        s = "a long string that should be truncated"
        result = truncate(s, limit)
        assert len(result) <= limit

    def test_truncation_replaces_last_char_with_ellipsis(self) -> None:
        result = truncate("abcdef", 4)
        # First 3 chars kept, 4th is ellipsis
        assert result == "abc\u2026"

    def test_large_limit_returns_original(self) -> None:
        s = "short"
        assert truncate(s, 1000) == s

